Key point 2: Decision table","target":{"path":"/lessons/03","hash":"#ch-3-2","query":{"tab-2":"code"}}},"121":{"title":"3.2 Colormap: 3 Types","breadcrumb":"Ch 3 · Color","kind":"code","text":"// 顺序型：[0, 1] → 颜色
d3.scaleSequential(d3.interpolateViridis);

