async function loadCSV() {
  try {
    const newstudent = await d3.csv("./newstudent.csv", function (d) {//本质上是在定义一个函数,d为参数
      return {
        id: +d.序号,
        name: d.姓名,
        gender: d.性别,
        age: +d.年龄,// 使用 "+" 运算符将字符串转换为数字
        cls: d.班级,
        province: d.生源省份,
