                const row = [];
                for (let j = 0; j < config.gridSize; j++) {
                    // 归一化坐标到 [-2, 2]
                    const x = (j / config.gridSize - 0.5) * 4;
                    const y = (i / config.gridSize - 0.5) * 4;

                    // 创建简单的测试函数
                    let value = Math.sin(x) * Math.cos(y);
                    value += 0.5 * Math.exp(-(x*x + y*y));

                    row.push(value);
                }
                gridData.push(row);
            }
            console.log("数据生成完成，范围:", 
                d3.min(gridData.flat()).toFixed(2), 
                "到", 
                d3.max(gridData.flat()).toFixed(2));
        }

        // 修复版的移动四边形法
        function marchingSquares(threshold) {
            const lines = [];
            const cellSizeX = config.canvasWidth / (config.gridSize - 1);
            const cellSizeY = config.canvasHeight / (config.gridSize - 1);

            console.log("计算等值线，阈值:", threshold);

