                    const topLeft = gridData[i][j];
                    const topRight = gridData[i][j + 1];
                    const bottomLeft = gridData[i + 1][j];
                    const bottomRight = gridData[i + 1][j + 1];

                    // 计算状态码
                    const state = 
                        (topLeft >= threshold ? 8 : 0) +
                        (topRight >= threshold ? 4 : 0) +
                        (bottomRight >= threshold ? 2 : 0) +
                        (bottomLeft >= threshold ? 1 : 0);

                    // 如果全高于或全低于阈值，跳过
                    if (state === 0 || state === 15) {
                        continue;
