                    // 线性插值函数
                    const interpolate = (pos1, pos2, val1, val2) => {
                        if (Math.abs(val1 - val2) < 0.0001) return pos1;
                        return pos1 + (pos2 - pos1) * (threshold - val1) / (val2 - val1);
