        const wrap = container.append('div')
          .attr('class', 'calendar-year')
          .attr('data-year', year)
          .style('cursor','pointer')
          .on('click', () => { if (window.renderSpiral) window.renderSpiral(year); });
        const header = wrap.append('div').attr('class', 'year-header');
        header.append('div').attr('class', 'year-title').text(`${year}`);

        const svg = wrap.append('svg')
          .attr('viewBox', `0 0 ${width} ${height}`)
          .attr('preserveAspectRatio', 'xMidYMid meet');

        const g = svg.append('g').attr('transform', `translate(${margin.left},${margin.top})`);

        const dow = ['一','二','三','四','五','六','日'];
        g.selectAll('text.dow-label')
          .data(dow)
          .join('text')
          .attr('class','dow-label')
          .attr('x', -8)
          .attr('y', (d,i) => (i + 0.75) * cellSize)
          .attr('text-anchor','end')
          .text(d => d);

        g.selectAll('rect.cell')
          .data(days)
          .join('rect')
          .attr('class','cell')
          .attr('width', cellSize - 1)
          .attr('height', cellSize - 1)
          // 每列的x基于以周一为起点的周序号，确保列内自上而下为周一到周日
          .attr('x', d => d3.timeMonday.count(d3.timeYear(d.date), d.date) * cellSize)
          .attr('y', d => dayIndexMonday(d.date) * cellSize)
          .attr('rx', 2).attr('ry', 2)
          .attr('fill', d => color(d.value))
          .on('mouseenter', (ev, d) => {
            const fmt = d3.timeFormat('%Y-%m-%d');
            tip.style('opacity', 1)
              .html(`<strong>${fmt(d.date)}</strong><br/>值：${d.value}`)
              .style('left', (ev.clientX + 12) + 'px')
              .style('top', (ev.clientY - 8) + 'px');
          })
          .on('mousemove', (ev) => {
            tip.style('left', (ev.clientX + 12) + 'px')
               .style('top', (ev.clientY - 8) + 'px');
          })
          .on('mouseleave', () => tip.style('opacity', 0))
          .on('click', (ev, d) => { if (window.renderSpiral) window.renderSpiral(d.date.getFullYear()); });

        const months = d3.timeMonth.range(s, d3.timeMonth.offset(e,1));
        g.append('g')
          .selectAll('path')
          .data(months)
          .join('path')
          .attr('class','month-boundary')
          .attr('d', m => monthPath(cellSize, m));

        const monthFmt = d3.timeFormat('%b');
        g.append('g')
          .selectAll('text.month-label')
          .data(months)
          .join('text')
          .attr('class','month-label')
          // 月份标签位置同样基于周一起点的周序号
          .attr('x', m => (d3.timeMonday.count(d3.timeYear(m), m) + 0.5) * cellSize)
          .attr('y', -6)
          .attr('text-anchor','middle')
          .text(m => monthFmt(m));
      });
    });

  const legend = d3.select('#legend');
  legend.append('span').attr('class','legend-text').text('低');
  d3.range(0, 6).forEach(i => {
    const v = i / 5 * 100;
    legend.append('div').attr('class','swatch').style('background', color(v));
  });
  legend.append('span').attr('class','legend-text').text('高');
