(function() {
  const csvPath = '/data/calendar_data_modified.csv';

  async function renderSpiral(yearDesired) {
    if (!window._spiralRows) {
      window._spiralRows = await d3.csv(csvPath, d => ({ date: new Date(d.date), value: +d.value || 0 }));
      window._spiralRows.sort((a,b) => a.date - b.date);
    }
    const rows = window._spiralRows;
    const years = Array.from(new Set(rows.map(r => r.date.getFullYear()))).sort((a,b) => a - b);
    const year = (yearDesired != null) ? yearDesired : years[years.length - 1];

    // 清空并重绘面板
    const panelSel = d3.select('#spiral-panel');
    panelSel.selectAll('*').remove();

  // 画布与坐标系配置
  const width = 800, height = 800;
  const svg = panelSel
    .append('svg')
    .attr('width', width)
    .attr('height', height)
    .attr('viewBox', `${-width/2} ${-height/2} ${width} ${height}`);

  // 与左侧热力图共享颜色尺度（0-100）
  const heatColor = window.heatColorScale || (window.heatColorScale = d3.scaleSequential(d3.interpolateRdYlGn).domain([0, 100]));

  // 文本颜色选择：根据背景颜色提高对比度
  function relLuminance(colorStr){
    const c = d3.color(colorStr);
    if(!c) return 0; // fallback
    const rgb = [c.r, c.g, c.b].map(v => {
      v /= 255;
      return v <= 0.03928 ? v/12.92 : Math.pow((v+0.055)/1.055, 2.4);
    });
    return 0.2126*rgb[0] + 0.7152*rgb[1] + 0.0722*rgb[2];
  }
  function contrastRatio(fg, bg){
    const L1 = relLuminance(fg) + 0.05;
    const L2 = relLuminance(bg) + 0.05;
    return L1 > L2 ? L1/L2 : L2/L1;
  }
  function pickTextColor(bg, prefer){
    const threshold = 4.5; // 小字号文本建议对比度
    if (prefer && contrastRatio(prefer, bg) >= threshold) return prefer;
    // 备选颜色中选择对比度最高的
    const candidates = ['#1a1d22', '#ffffff', '#eaeef4'];
    let best = candidates[0], bestRatio = 0;
    for (const c of candidates){
      const r = contrastRatio(c, bg);
      if (r > bestRatio){ best = c; bestRatio = r; }
    }
    return best;
  }

  const centerX = 0, centerY = 0;

  // 极坐标核心参数
  // 1. 数据准备：直接加载 CSV 并构造该年份的完整日期数组，缺失填充
  const fmtISO = d3.timeFormat('%Y-%m-%d');
  const byKey = new Map(rows.map(r => [fmtISO(r.date), r.value]));
  const startDate = new Date(year, 0, 1);
  const endDate = new Date(year, 11, 31);
  const months = d3.range(1, 13);
  const data = d3.timeDay.range(startDate, d3.timeDay.offset(endDate, 1)).map(dt => {
    const m = dt.getMonth() + 1;
    const iso = fmtISO(dt);
    return {
      year,
      month: m,
      day: dt.getDate(),
      weekDay: dt.getDay(),
      monthDays: new Date(year, m, 0).getDate(),
      id: iso,
      value: byKey.get(iso) ?? 0
    };
  });

  // 2. 螺旋坐标参数（阿基米德螺旋 r = a + bθ）
  const boxSize = 32;
  const stepLen = boxSize;               // 邻接：步长等于方框宽度
  const a = -0;                          // 初始半径（调小以缩小中心空洞）
  const coilGap = boxSize;               // 希望相邻圈之间的径向间距等于方框厚度
  const b = coilGap / (2 * Math.PI);     // 使相邻圈几乎无缝贴合（Δr = 2πb = boxSize）
  const rStart = 360;                    // 起始半径，保证一月在最外层
  let theta = (rStart - a) / b;          // 从外沿开始
  const thetaStart = theta;              // 记录开始角度用于绘制整体边界

  // 计算当前位置与切线角度
  function pos(t) {
    const r = a + b * t;
    const x = r * Math.cos(t);
    const y = r * Math.sin(t);
    const dxdt = b * Math.cos(t) - r * Math.sin(t);
    const dydt = b * Math.sin(t) + r * Math.cos(t);
    const tangentDeg = Math.atan2(dydt, dxdt) * 180 / Math.PI;
    return { r, x, y, tangentDeg };
  }

  // 螺旋边界坐标（外/内）
  function posOuter(t) {
    const r = a + b * t + coilGap/2;
    return { x: r * Math.cos(t), y: r * Math.sin(t) };
  }
  function posInner(t) {
    const r = a + b * t - coilGap/2;
    return { x: r * Math.cos(t), y: r * Math.sin(t) };
