  // 生成沿螺旋的扇环段路径（相邻段边界一致，保证无缝）
  function segmentPath(t0, t1, samples = 6) {
    const dt = (t1 - t0) / samples;
    let d = '';
    // 外边界：t0 -> t1
    let t = t0;
    let p = posOuter(t);
    d += `M ${p.x} ${p.y}`;
    for (let i=1; i<=samples; i++) {
      t = t0 + dt * i;
      p = posOuter(t);
      d += ` L ${p.x} ${p.y}`;
    }
