        .attr('transform', `translate(${mid.x},${mid.y})`)
        .text(ch);
      // 扇环两条径向直边的淡色描边
      const p0o = posOuter(t0), p0i = posInner(t0);
      const p1o = posOuter(t1), p1i = posInner(t1);
      edgesLayer.append('line')
