  // 2. 螺旋坐标参数（阿基米德螺旋 r = a + bθ）
  const boxSize = 32;
  const stepLen = boxSize;               // 邻接：步长等于方框宽度
  const a = -0;                          // 初始半径（调小以缩小中心空洞）
  const coilGap = boxSize;               // 希望相邻圈之间的径向间距等于方框厚度
  const b = coilGap / (2 * Math.PI);     // 使相邻圈几乎无缝贴合（Δr = 2πb = boxSize）
  const rStart = 360;                    // 起始半径，保证一月在最外层
  let theta = (rStart - a) / b;          // 从外沿开始
  const thetaStart = theta;              // 记录开始角度用于绘制整体边界

  // 计算当前位置与切线角度
  function pos(t) {
    const r = a + b * t;
    const x = r * Math.cos(t);
    const y = r * Math.sin(t);
    const dxdt = b * Math.cos(t) - r * Math.sin(t);
    const dydt = b * Math.sin(t) + r * Math.cos(t);
    const tangentDeg = Math.atan2(dydt, dxdt) * 180 / Math.PI;
    return { r, x, y, tangentDeg };
  }

  // 螺旋边界坐标（外/内）
  function posOuter(t) {
    const r = a + b * t + coilGap/2;
    return { x: r * Math.cos(t), y: r * Math.sin(t) };
  }
  function posInner(t) {
    const r = a + b * t - coilGap/2;
    return { x: r * Math.cos(t), y: r * Math.sin(t) };
  }

  // 生成沿螺旋的扇环段路径（相邻段边界一致，保证无缝）
  function segmentPath(t0, t1, samples = 6) {
    const dt = (t1 - t0) / samples;
    let d = '';
    // 外边界：t0 -> t1
    let t = t0;
    let p = posOuter(t);
    d += `M ${p.x} ${p.y}`;
    for (let i=1; i<=samples; i++) {
      t = t0 + dt * i;
      p = posOuter(t);
      d += ` L ${p.x} ${p.y}`;
    }
    // 内边界：t1 -> t0（回程）
    for (let i=samples; i>=0; i--) {
      t = t0 + dt * i;
      p = posInner(t);
      d += ` L ${p.x} ${p.y}`;
    }
    d += ' Z';
    return d;
  }

  function segmentMid(t0, t1) {
    const tm = (t0 + t1) / 2;
    return pos(tm);
  }

  // 按给定曲线长度前进，返回新位置
  function advance(len, dir = -1) { // 默认向内推进
    const r = a + b * theta;
    const dtheta = (len / Math.sqrt(b*b + r*r)) * dir;
    theta += dtheta;
    const p = pos(theta);
    spiralPoints.push([p.x, p.y]);
    return p;
  }

  // 3. 分层分组与中心文字
  const centerMain = root.append('text')
     .attr('class','center-main')
     .attr('x', centerX)
     .attr('y', centerY + 2)
     .text(year);
  const centerSub = root.append('text')
     .attr('class','center-sub')
     .attr('x', centerX)
     .attr('y', centerY + 26)
     .text('');
  const spiralLayer = root.append('g').attr('class','spiral');
  const itemsLayer = root.append('g').attr('class','items');
  const edgesLayer  = root.append('g').attr('class','edges');
  // 新增：用于动画逐步显示的日段分组（按月份分桶）
  const daysByMonthGroup = new Map();

  // 4. 顺序沿螺旋绘制：月份缩写 + 日期方框
  const monthsAbbr = ['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];
  const monthLettersMap = new Map();
  const spiralPoints = [];
  spiralPoints.push([pos(theta).x, pos(theta).y]);

  const dataByMonth = d3.group(data, d => d.month);
  // 英文星期的前两个字母（首字母大写、第二个字母小写）
  const weekTwoLettersEn = ['Su','Mo','Tu','We','Th','Fr','Sa'];
  const weekNamesZh = ['周日','周一','周二','周三','周四','周五','周六'];

  months.forEach(m => {
    // 首字母单扇环段，并与后续日期段无缝衔接
    const ch = monthsAbbr[m-1];
    const letterSegs = [];
    {
      const t0 = theta;
      const r = a + b * t0;
      const dtheta = (stepLen / Math.sqrt(b*b + r*r)) * -1;
      const t1 = t0 + dtheta;
      const pathD = segmentPath(t0, t1);
      const pathSel = itemsLayer.append('path')
        .attr('class', 'seg letter-seg')
        .attr('d', pathD);
      const mid = segmentMid(t0, t1);
      itemsLayer.append('text')
        .attr('class','letter-text')
        .attr('transform', `translate(${mid.x},${mid.y})`)
        .text(ch);
      // 扇环两条径向直边的淡色描边
      const p0o = posOuter(t0), p0i = posInner(t0);
      const p1o = posOuter(t1), p1i = posInner(t1);
      edgesLayer.append('line')
        .attr('class','segment-edge')
        .attr('x1', p0o.x).attr('y1', p0o.y)
        .attr('x2', p0i.x).attr('y2', p0i.y);
      edgesLayer.append('line')
        .attr('class','segment-edge')
        .attr('x1', p1o.x).attr('y1', p1o.y)
        .attr('x2', p1i.x).attr('y2', p1i.y);
      letterSegs.push(pathSel.node());
      theta = t1;
      spiralPoints.push([mid.x, mid.y]);
    }
    monthLettersMap.set(m, letterSegs);

    // 绘制本月的每一天，方框沿曲线等距分布、紧挨排列
    const monthDays = dataByMonth.get(m);
    // 为每个月建立一个子分组，初始不显示（opacity 0），待动画逐日显示
    const monthDaysGroup = itemsLayer.append('g')
      .attr('class', `month-days month-${m}`)
      .attr('opacity', 0);
    daysByMonthGroup.set(m, monthDaysGroup);

    monthDays.forEach(d => {
      const t0 = theta;
      const r = a + b * t0;
      const dtheta = (stepLen / Math.sqrt(b*b + r*r)) * -1;
      const t1 = t0 + dtheta;
      const pathD = segmentPath(t0, t1);
      // 扇环背景颜色按天与热力图对应（共享颜色尺度）
      const fillColor = heatColor(d.value);
      const pathSel = monthDaysGroup.append('path')
        .attr('class', 'seg')
        .attr('d', pathD)
        .attr('fill', fillColor)
        .attr('data-iso', d.id);
      const mid = segmentMid(t0, t1);
      const preferColor = (d.weekDay === 0 || d.weekDay === 1) ? '#ee9b4c' : '#9e9e9e';
      const textColor = pickTextColor(fillColor, preferColor);
      const textSel = monthDaysGroup.append('text')
        .attr('class','seg-text')
        .attr('transform', `translate(${mid.x},${mid.y})`)
        .attr('fill', textColor)
        .attr('data-iso', d.id)
        .text(`${weekTwoLettersEn[d.weekDay]} ${d.day}`);

      // 扇环两条径向直边的淡色描边
      const q0o = posOuter(t0), q0i = posInner(t0);
      const q1o = posOuter(t1), q1i = posInner(t1);
      edgesLayer.append('line')
        .attr('class','segment-edge')
        .attr('x1', q0o.x).attr('y1', q0o.y)
        .attr('x2', q0i.x).attr('y2', q0i.y);
      edgesLayer.append('line')
        .attr('class','segment-edge')
        .attr('x1', q1o.x).attr('y1', q1o.y)
        .attr('x2', q1i.x).attr('y2', q1i.y);

      pathSel.on('click', () => {
        if (window.selectDay) window.selectDay(d.id);
      });
      textSel.on('click', () => {
        if (window.selectDay) window.selectDay(d.id);
      });

      pathSel.append('title')
        .text(`${d.year}年${d.month}月${d.day}日 ${weekNamesZh[d.weekDay]} 值：${d.value}`);

      theta = t1;
      spiralPoints.push([mid.x, mid.y]);
    });
  });

  // 5. 绘制螺旋参考路径（置于底层）
  const line = d3.line().curve(d3.curveNatural);
  spiralLayer.append('path')
    .attr('class','spiral-path')
    .attr('d', line(spiralPoints));

  // 6. 绘制整体外/内边界线以增强对比（颜色独立于段填充）
  const thetaEnd = theta; // 当前为结束角度（已经推进到最后）
  const stepEdge = 0.05;  // 采样步长，越小越平滑
  const outerPts = [];
  const innerPts = [];
  for (let t = thetaStart; t >= thetaEnd; t -= stepEdge) {
    const po = posOuter(t);
    const pi = posInner(t);
    outerPts.push([po.x, po.y]);
    innerPts.push([pi.x, pi.y]);
  }
  edgesLayer.append('path')
    .attr('class','spiral-edge')
    .attr('d', d3.line()(outerPts));
  edgesLayer.append('path')
    .attr('class','spiral-edge')
    .attr('d', d3.line()(innerPts));

  // 动画：先显示月份扇环，再并行从每月1号逐步显示到月底
  // 1) 立即显示月份首字母扇环（已绘制可见），保持日段分组隐藏（opacity 0）
  // 2) 并行逐日显示：按 day=1..31 循环，对每个月选择对应日的元素显示
  const maxDays = 31;
  const stepMs = 40; // 每一日的步进时长
  const easeFn = d3.easeCubicOut;

  if (animate) {
    // 构建每月每日的选择器缓存，提高选择效率
    const monthDaySelectors = new Map();
    daysByMonthGroup.forEach((gSel, m) => {
      const nodes = gSel.selectAll('path.seg').nodes();
      const textNodes = gSel.selectAll('text.seg-text').nodes();
      monthDaySelectors.set(m, { paths: nodes, texts: textNodes });
    });

    // 先把各月分组整体淡入（仅显示容器，不显示具体日元素）
    daysByMonthGroup.forEach((gSel) => {
      gSel.transition().duration(200).attr('opacity', 1);
      // 初始化：隐藏子元素
      gSel.selectAll('path.seg').style('opacity', 0);
      gSel.selectAll('text.seg-text').style('opacity', 0);
    });

    // 并行按日索引逐步显示
    for (let dayIndex = 1; dayIndex <= maxDays; dayIndex++) {
      const delay = dayIndex * stepMs;
      daysByMonthGroup.forEach((gSel, m) => {
        const sel = monthDaySelectors.get(m);
        if (!sel) return;
        const idx = dayIndex - 1;
        if (idx < sel.paths.length) {
          const pathNode = sel.paths[idx];
          const textNode = sel.texts[idx];
          d3.select(pathNode)
            .transition()
            .delay(delay)
            .duration(220)
            .ease(easeFn)
            .style('opacity', 1);
          d3.select(textNode)
            .transition()
            .delay(delay)
            .duration(220)
            .ease(easeFn)
            .style('opacity', 1);
        }
      });
    }
  } else {
    // 同一年重复点击：直接显示，无动画
    daysByMonthGroup.forEach((gSel) => {
      gSel.attr('opacity', 1);
      gSel.selectAll('path.seg').style('opacity', 1);
      gSel.selectAll('text.seg-text').style('opacity', 1);
    });
  }

  // 记录本次展示年份，用于控制后续动画出现与否
  window._spiralLastYear = year;
  }

  // 全局：高亮螺旋中的某一天，并更新中心信息
  window.highlightSpiralDay = function(iso) {
    const panel = d3.select('#spiral-panel');
    panel.selectAll('.seg.highlight').classed('highlight', false);
    const seg = panel.select(`path.seg[data-iso="${iso}"]`);
    seg.classed('highlight', true);
    // 将高亮段置顶，避免被其他段覆盖
    try { seg.raise(); } catch(e) {}
    // 同步将文字也置顶，确保不被其他元素遮挡
    const segText = panel.select(`text.seg-text[data-iso="${iso}"]`);
    try { segText.raise(); } catch(e) {}
    // 触发一次呼吸动画
    try {
      seg.classed('pulse', true);
      segText.classed('pulse', true);
      setTimeout(() => {
        seg.classed('pulse', false);
        segText.classed('pulse', false);
      }, 650);
    } catch(e) {}
    // 更新中心信息
    const dt = new Date(iso);
    const value = (window._spiralByKey && window._spiralByKey.get(iso)) ?? 0;
    const weekNamesZh = ['周日','周一','周二','周三','周四','周五','周六'];
    panel.select('text.center-main').text(`${dt.getFullYear()}年${dt.getMonth()+1}月${dt.getDate()}日`);
    panel.select('text.center-sub').text(`${weekNamesZh[dt.getDay()]} ${value}`);
  };

  // 全局：高亮热力图中的某一天格子
  window.highlightHeatCell = function(iso) {
    const cal = d3.select('#calendar');
    cal.selectAll('rect.cell.active').classed('active', false);
    const cell = cal.select(`rect.cell[data-iso="${iso}"]`);
    cell.classed('active', true);
    // 置顶以确保高亮边框不被月边界遮挡
    try { cell.raise(); } catch(e) {}
    // 触发一次呼吸动画
    try {
      cell.classed('pulse', true);
      setTimeout(() => { cell.classed('pulse', false); }, 650);
    } catch(e) {}
  };

  // 清除左侧热力图的高亮（用于右侧年份切换后）
  window.clearHeatHighlight = function() {
    const cal = d3.select('#calendar');
    cal.selectAll('rect.cell.active').classed('active', false);
  };

  // 全局：选择某一天，跨图联动与必要的年份切换
  window.selectDay = function(iso) {
    // 左侧高亮
    window.highlightHeatCell(iso);
    const targetYear = new Date(iso).getFullYear();
    const currentYear = window._spiralLastYear;
    if (currentYear === undefined || currentYear !== targetYear) {
      if (window.renderSpiral) {
        window.renderSpiral(targetYear).then(() => {
          window.highlightSpiralDay(iso);
        });
      }
    } else {
      window.highlightSpiralDay(iso);
    }
  };
  window.renderSpiral = renderSpiral;
  renderSpiral();
